class Cache
  Entry = Struct.new(:value, :stored_at)

  def initialize(capacity, ttl)
    @capacity = capacity
    @ttl = ttl
    @store = {}
  end

  def put(key, value, now)
    @store.delete(key)
    if @store.size >= @capacity
      oldest_key = @store.keys.first
      @store.delete(oldest_key)
    end
    @store[key] = Entry.new(value, now)
  end

  def get(key, now)
    entry = @store[key]
    return nil if entry.nil?
    if now - entry.stored_at >= @ttl
      @store.delete(key)
      return nil
    end
    @store.delete(key)
    @store[key] = entry
    entry.value
  end
end

